import{_ as n,D as e,o as p,c as s,m as i,a as h,G as l,S as c}from"./chunks/framework.DuIEtbrD.js";const q=JSON.parse('{"title":"JS垃圾回收机制","description":"JavaScript语言是如何高效的帮助用户进行垃圾回收的,一起来揭秘JS的垃圾回收吧","frontmatter":{"title":"JS垃圾回收机制","description":"JavaScript语言是如何高效的帮助用户进行垃圾回收的,一起来揭秘JS的垃圾回收吧","keywords":"JS垃圾回收机制,垃圾回收,内存释放,引用计数法,标记清除法,分代式回收","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/icon-js.png"},"headers":[],"relativePath":"frontend/js/js-gc.md","filePath":"frontend/js/js-gc.md","lastUpdated":1776945570000}'),d={name:"frontend/js/js-gc.md"};function u(m,a,b,f,S,g){const r=e("Obsolete"),t=e("Reward"),o=e("Gitalk");return p(),s("div",null,[a[0]||(a[0]=i("h1",{id:"js垃圾回收机制",tabindex:"-1"},[h("JS垃圾回收机制 "),i("a",{class:"header-anchor",href:"#js垃圾回收机制","aria-label":'Permalink to "JS垃圾回收机制"'},"​")],-1)),l(r,{date:"2019-09-22"}),a[1]||(a[1]=c('<p>在 JavaScript 中，内存管理是开发者经常忽略却至关重要的一部分。与某些底层语言不同，JavaScript 的运行环境（如浏览器和 Node.js）配备了自动垃圾回收机制，帮助开发者管理内存分配和释放，避免手动清理的复杂性。然而，这种“自动化”并不意味着完全无需关注。了解垃圾回收的原理、运行机制和潜在问题，不仅能帮助我们优化代码性能，还能有效避免内存泄漏等隐性问题。本文将从 JavaScript 垃圾回收机制的核心概念入手，解析其工作原理及在实际开发中的重要性</p><h2 id="引用计数法" tabindex="-1">引用计数法 <a class="header-anchor" href="#引用计数法" aria-label="Permalink to &quot;引用计数法&quot;">​</a></h2><p>引用计数法是早期垃圾回收算法的一种，它通过追踪每个对象的引用次数来判断该对象是否可以被回收。在 JavaScript 的垃圾回收机制中，引用计数法是重要的一部分，尽管它已不再是主流，但理解这一机制对于掌握 JavaScript 内存管理至关重要</p><p>引用计数法的核心思想是：</p><ul><li>每个对象维护一个 引用计数器，表示该对象被引用的次数</li><li>增加引用：当一个变量引用该对象时，引用计数 +1</li><li>减少引用：当一个引用失效（如变量被重新赋值为 null 或指向其他对象）时，引用计数 -1</li><li>回收对象：当某个对象的引用计数为 0 时，认为该对象不可达，即无其他部分会使用它，垃圾回收器会释放该对象占用的内存</li></ul><p>这种垃圾回收机制虽然简单，但是存在明显的缺陷：</p><ul><li>优点：引用计数只需要在计数为0 时就可以回收，不需要遍历所有对象</li><li>缺点：计数器需要占很大的空间，无法解决循环引用无法回收的问题</li></ul><h2 id="标记清除法" tabindex="-1">标记清除法 <a class="header-anchor" href="#标记清除法" aria-label="Permalink to &quot;标记清除法&quot;">​</a></h2><p>标记清除法（Mark-and-Sweep）是现代 JavaScript 引擎中最常用的一种垃圾回收算法。它有效解决了引用计数法的循环引用问题，并成为垃圾回收机制的核心基础算法。标记清除法通过标记可达对象和清除不可达对象的方式，自动释放内存中不再使用的数据</p><p>工作流程：</p><ul><li>根对象出发：从全局对象（如 window 或 global）以及当前执行上下文的作用域链开始，找到所有可达对象</li><li>标记阶段：标记所有可达对象，表示它们是活跃的</li><li>清除阶段：扫描内存中未被标记的对象，将其占用的内存释放</li><li>内存整理（可选）：有些引擎会对内存中的对象进行整理，减少碎片化，提高内存分配效率</li></ul><p>标记清除法的局限性：</p><ul><li>暂停执行的性能开销：标记清除法需要扫描内存中的所有对象，标记和清除过程会暂停应用程序的执行（即 Stop-the-World），在大规模对象中可能导致卡顿</li><li>内存碎片化问题：清除不可达对象后，内存中可能会留下很多不连续的小空闲空间，导致内存碎片化，影响后续的内存分配</li><li>频繁触发影响性能：如果垃圾回收器频繁运行（如在高密集内存使用场景中），可能会对应用性能产生明显影响</li></ul><h2 id="分代式回收" tabindex="-1">分代式回收 <a class="header-anchor" href="#分代式回收" aria-label="Permalink to &quot;分代式回收&quot;">​</a></h2><p>为了解决标记清除法的局限性，现代 JavaScript 引擎对其进行了多种优化，如 V8 引擎广泛采用了分代式垃圾回收机制</p><p>对象的生命周期长短具有规律性，大多数对象的生命周期较短，少数对象的生命周期较长。 基于此，分代式垃圾回收将内存分为两部分：</p><ul><li>新生代（Young Generation）：存储生命周期短的对象</li><li>老生代（Old Generation）：存储生命周期长的对象</li></ul><h3 id="新生代" tabindex="-1">新生代 <a class="header-anchor" href="#新生代" aria-label="Permalink to &quot;新生代&quot;">​</a></h3><p>新生代使用Scavenge算法、Cheney算法，Cheney算法将新生代内存一分为二，使用区和空闲区，对活动区的对象进行标记，清理，活动区和空闲区身份互换，交换两次后，将活动区还在的老对象放到老生代，如果交换后空闲区超过25%，将会把对象都放到老生代</p><h3 id="老生代" tabindex="-1">老生代 <a class="header-anchor" href="#老生代" aria-label="Permalink to &quot;老生代&quot;">​</a></h3><p>老生代存放一些空间大、存活时间长，如果放在新生代频繁复制交换，会非常耗时；老生代使用标记清除法，进行清除，排序整理，标记整理并行回收，读写锁全停顿，增量标记、三色标记、写屏障惰性清理</p><h2 id="并行回收" tabindex="-1">并行回收 <a class="header-anchor" href="#并行回收" aria-label="Permalink to &quot;并行回收&quot;">​</a></h2><p>并行回收是一种优化的垃圾回收技术，它通过利用多核 CPU 的优势，在垃圾回收阶段同时运行多个线程，以加速垃圾回收过程。在传统垃圾回收机制中，垃圾回收器通常是单线程运行的，所有的回收任务都由一个线程顺序执行。当垃圾回收过程启动时，整个程序会暂停（即“Stop-the-World”）。随着现代计算机硬件的多核化，利用多线程并行处理垃圾回收任务，能显著缩短回收时间</p><p>工作流程：</p><ul><li><p>(1) <code>标记阶段的并行化</code>：垃圾回收器会从根对象（如全局对象、函数调用栈）开始，递归标记所有可达的对象。 在并行回收中，多个线程同时参与标记任务，分工处理不同的内存区域，减少单线程标记的耗时</p></li><li><p>(2) <code>清除阶段的并行化</code>：对未标记的不可达对象进行清理，并释放其占用的内存 并行回收通过多线程同时扫描内存的不同区域，加速垃圾的清除过程。</p></li></ul><h2 id="增量标记" tabindex="-1">增量标记 <a class="header-anchor" href="#增量标记" aria-label="Permalink to &quot;增量标记&quot;">​</a></h2><p>增量标记将垃圾回收中的标记阶段分解为多个小的增量步骤，允许垃圾回收器和应用程序线程交替运行。这种方式特别适合对实时性要求较高的应用程序场景，如交互式界面或游戏开发</p><p>增量标记的核心在于将标记阶段分解为多个小步骤，而不是一次性完成整个标记过程。通过这种方式，应用程序线程在垃圾回收过程中能够继续执行，从而减少用户感知到的卡顿现象</p><p>在增量标记中，垃圾回收器使用了写屏障（Write Barrier）和三色标记法来保证标记过程的一致性</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_21.20.58.png" alt=""></p><h3 id="三色标记法" tabindex="-1">三色标记法 <a class="header-anchor" href="#三色标记法" aria-label="Permalink to &quot;三色标记法&quot;">​</a></h3><p>增量标记中，对象分为三种颜色，以追踪其标记状态：</p><ul><li>白色（未访问）：尚未被标记的对象，默认所有对象最初为白色</li><li>灰色（已访问但未处理引用）：标记为可达，但其引用的对象尚未全部标记</li><li>黑色（已访问且已处理引用）：标记为可达，且其引用的对象已全部标记</li></ul><p>垃圾回收器在增量阶段逐步将对象从白色转为灰色，再转为黑色</p><h3 id="写屏障" tabindex="-1">写屏障 <a class="header-anchor" href="#写屏障" aria-label="Permalink to &quot;写屏障&quot;">​</a></h3><p>写屏障是一种机制，用于跟踪增量标记阶段对象引用的变动</p><p>如果应用程序线程修改了对象的引用关系，写屏障会记录下变动的对象，并在下一次标记时处理这些对象； 这样可以保证增量标记过程的正确性，避免漏标对象</p><h2 id="惰性清除" tabindex="-1">惰性清除 <a class="header-anchor" href="#惰性清除" aria-label="Permalink to &quot;惰性清除&quot;">​</a></h2><p>传统的垃圾回收算法（如标记-清除）中，在标记阶段标记出不可达对象后，清除阶段会一次性清理所有垃圾对象。这种方式虽然简单，但当内存中的垃圾对象较多时，清除阶段可能会导致应用程序暂停较长时间，从而影响用户体验</p><p>惰性清除的核心在于延迟清除垃圾对象，并将清除任务分散到后续的内存分配或空闲时间中。具体表现为：</p><ul><li>标记阶段：像传统的标记-清除算法一样，标记所有可达对象</li><li>清除阶段：不立即清除所有未标记的对象，而是将它们保留在空闲列表中；在下一次分配内存时，只清除需要的部分垃圾对象以腾出足够的空间</li></ul><h2 id="并发回收" tabindex="-1">并发回收 <a class="header-anchor" href="#并发回收" aria-label="Permalink to &quot;并发回收&quot;">​</a></h2><p>V8 引擎采用了 分代回收（Generational Garbage Collection）和 并发标记清除（Concurrent Mark-and-Sweep）算法</p><ul><li>分代回收：V8 会将对象分为 年轻代（Young Generation）和 老年代（Old Generation）。年轻代的对象生命周期较短，回收频繁；老年代的对象生命周期较长，回收较少</li><li>并发标记清除：垃圾回收的标记阶段在后台线程中与应用程序代码并发执行。清除阶段可能会暂停应用程序，但可以使用 增量清除 和 并发清除 的策略，减少停顿时间</li></ul><p>并发回收的优势：</p><ul><li>减少停顿时间：传统的垃圾回收可能会导致长时间的停顿，影响用户体验。并发回收可以将垃圾回收工作分散到多个时间点进行，从而缩短每次停顿的时间</li><li>平滑用户体验：通过并发执行，应用程序的响应性得到了保持，避免了长时间卡顿</li></ul><h2 id="参考文档" tabindex="-1">参考文档 <a class="header-anchor" href="#参考文档" aria-label="Permalink to &quot;参考文档&quot;">​</a></h2><ul><li><a href="https://v8.js.cn/blog/concurrent-marking/" target="_blank" rel="noreferrer">v8.js</a></li><li><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Memory_management" target="_blank" rel="noreferrer">JS Memory_management</a></li><li><a href="https://www.youtube.com/watch?v=easvMCCBFkQ" target="_blank" rel="noreferrer">COST of JavaScript’s GC REALLY</a></li></ul>',48)),l(t),l(o)])}const v=n(d,[["render",u]]);export{q as __pageData,v as default};
